mapper.sql:
WHERE h.deleted_yn = 'N' AND l.deleted_yn = 'N'
AND h.business_date > = TO_DATE(#{startDate}, 'YYYY-MM-DD')
AND h.business_date < = TO_DATE(#{endDate}, 'YYYY-MM-DD') + 1
AND UPPER(h.quotation_no) LIKE '%' || UPPER(TRIM(#{quotationNo})) || '%'
AND h.progress_status = #{progressStatus}
AND UPPER(l.specification) LIKE '%' || UPPER(TRIM(#{specification})) || '%'
AND h.warehouse_id IN
#{warehouseId}
AND h.partner_id IN
#{partnerId}
AND l.item_id IN
#{itemId}
AND h.assignee_id IN
#{assigneeId}
AND l.unit_price >=#{minUnitPrice}
AND l.unit_price <=#{maxUnitPrice}
AND ( UPPER(h.quotation_no) LIKE '%' || TRIM(#{keyword}) || '%' OR TO_CHAR(h.business_date, 'YYYY-MM-DD') LIKE '%' || TRIM(#{keyword}) || '%' OR TO_CHAR(h.business_date, 'YYYY/MM/DD') LIKE '%' || TRIM(#{keyword}) || '%' OR UPPER(i.item_code) LIKE '%' || TRIM(#{keyword}) || '%' OR UPPER(l.item_name) LIKE '%' || TRIM(#{keyword}) || '%' OR UPPER(l.specification) LIKE '%' || TRIM(#{keyword}) || '%' OR UPPER(l.unit) LIKE '%' || TRIM(#{keyword}) || '%' OR UPPER(h.partner_name) LIKE '%' || TRIM(#{keyword}) || '%' OR UPPER(h.warehouse_name) LIKE '%' || TRIM(#{keyword}) || '%' OR UPPER(h.assignee_name) LIKE '%' || TRIM(#{keyword}) || '%' OR UPPER(h.note) LIKE '%' || TRIM(#{keyword}) || '%' OR UPPER(l.note) LIKE '%' || TRIM(#{keyword}) || '%' )

mapper.select:
select 
from QUOTATION h
join QUOTATION_LINE l on l.quotation_id = h.quotation_id
left join item i on i.item_id = l.item_id




	AND l.quantity >= #{minQuantity}


	AND l.quantity <= #{maxQuantity}


	AND l.supply_amount >= #{minSupplyAmount}


	AND l.supply_amount <= #{maxSupplyAmount}


	AND l.vat_amount >= #{minVatAmount}


	AND l.vat_amount <= #{maxVatAmount}

ORDER BY h.business_date ASC, h.quotation_id ASC, l.quotation_line_id ASC
